select 
from merchant_crm_campaign c
where c.merchant_id = #{merchantId}
order by c.id desc
limit #{limit}

select 
from merchant_crm_campaign_recipient
where merchant_id = #{merchantId} and campaign_id = #{campaignId}
order by id asc
limit #{limit}

select count(1) from merchant_crm_campaign_recipient
where merchant_id = #{merchantId} and member_id = #{memberId} and channel = #{channel}
  and status = 'DELIVERED' and campaign_id <> #{campaignId}
  and delivered_at >= current_date and delivered_at < date_add(current_date, interval 1 day)

mapper.update:
update merchant_crm_campaign c
set c.processing_token = #{processingToken},
    c.processing_lease_until = date_add(now(3), interval #{leaseSeconds} second),
    c.version = c.version + 1, c.update_time = now()
where c.merchant_id = #{merchantId} and c.id = #{campaignId}
  and c.merchant_owner_member_id = #{ownerMemberId}
  and c.status = 'PROCESSING' and c.processing_lease_until < now(3)
  and c.version = #{expectedVersion}
  and exists (
    select 1 from mms_merchant m
    where m.id = c.merchant_id and m.member_id = c.merchant_owner_member_id
      and m.status = 1 and m.account_status = 1 and m.del_flag = 0
  )

update merchant_crm_campaign c
set c.status = 'NO_ELIGIBLE', c.finished_at = now(),
    c.processing_token = null, c.processing_lease_until = null,
    c.version = c.version + 1, c.update_time = now()
where c.merchant_id = #{merchantId} and c.id = #{campaignId}
  and c.merchant_owner_member_id = #{ownerMemberId}
  and c.status = 'PROCESSING' and c.processing_lease_until < now(3)
  and c.version = #{expectedVersion}
  and not exists (
    select 1 from mms_merchant m
    where m.id = c.merchant_id and m.member_id = c.merchant_owner_member_id
      and m.status = 1 and m.account_status = 1 and m.del_flag = 0
  )

update merchant_crm_campaign c
set c.status = 'NO_ELIGIBLE', c.finished_at = now(),
    c.processing_token = null, c.processing_lease_until = null,
    c.version = c.version + 1, c.update_time = now()
where c.merchant_id = #{merchantId} and c.id = #{campaignId}
  and c.merchant_owner_member_id = #{ownerMemberId}
  and c.status = 'PROCESSING' and c.processing_token = #{processingToken}
  and not exists (
    select 1 from mms_merchant m
    where m.id = c.merchant_id and m.member_id = c.merchant_owner_member_id
      and m.status = 1 and m.account_status = 1 and m.del_flag = 0
  )

update merchant_crm_campaign c
set c.processing_lease_until = date_add(now(3), interval #{leaseSeconds} second), c.update_time = now()
where c.merchant_id = #{merchantId} and c.id = #{campaignId}
  and c.status = 'PROCESSING' and c.processing_token = #{processingToken}
  and exists (
    select 1 from mms_merchant m
    where m.id = c.merchant_id and m.member_id = c.merchant_owner_member_id
      and m.status = 1 and m.account_status = 1 and m.del_flag = 0
  )

update merchant_crm_delivery_guard
set status = 'DISPATCHING', lease_until = date_add(now(3), interval #{leaseSeconds} second),
    version = version + 1, update_time = now(3)
where id = #{guardId} and status = 'RESERVED' and lease_token = #{leaseToken}
  and lease_until >= now(3) and version = #{expectedVersion}

update merchant_crm_delivery_guard
set status = 'DELIVERED', lease_token = null, lease_until = null,
    message_receipt_id = #{messageReceiptId}, coupon_history_id = #{couponHistoryId},
    failure_code = null, version = version + 1, update_time = now(3)
where id = #{guardId} and status = 'DISPATCHING' and lease_token = #{leaseToken}
  and version = #{expectedVersion}

update merchant_crm_delivery_guard
set status = 'RESERVED', lease_until = date_sub(now(3), interval 1 second),
    failure_code = null, version = version + 1, update_time = now(3)
where id = #{guardId} and status = 'DISPATCHING' and lease_token = #{leaseToken}
  and version = #{expectedVersion}

update merchant_crm_delivery_guard
set status = 'FAILED_UNCERTAIN', lease_token = null, lease_until = null,
    failure_code = #{failureCode}, version = version + 1, update_time = now(3)
where id = #{guardId} and status = 'DISPATCHING' and lease_token = #{leaseToken}
  and version = #{expectedVersion}
